#include "accumulationRegister.h"

/* PNG */
static const wxString s_accumRegister_16_png = wxT("");

wxIcon ibValueMetaObjectAccumulationRegister::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectAccumulationRegister::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_accumRegister_16_png, wxSize(16, 16));

	return icon;
}
